import os
import binascii


def import_settings_from_environment_variables(config):
    """Import settings from environment variables into the config dict."""
    for key, value in os.environ.items():
        if key.startswith('SYNCSERVER_'):
            config_key = key[len('SYNCSERVER_'):].lower()
            config[config_key] = value
    return config


def str_to_bool(value):
    """Convert a string to a boolean."""
    if isinstance(value, bool):
        return value
    return value.lower() in ('true', '1', 'yes', 'on')


def generate_random_hex_key(num_bytes=16):
    """Generate a random hex key of specified length (default 32 chars)."""
    return binascii.hexlify(os.urandom(num_bytes)).decode('ascii')
